(@Human,    @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@Orc,      @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@Dwarf,    @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@NightElf, @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@Undead,   @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@Tauren,   @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@Gnome,    @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@Troll,    @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
(@BloodElf, @DeathKnight, @Northrend,       @ScarletEnclave, @DKStartX,       @DKStartY,       @DKStartZ,       @DKStartO),
